import React, { useEffect, useState } from 'react';
import api from '../../api/axios';

export default function PageHistorique() {
  const [connexions, setConnexions] = useState([]);
  const [loading, setLoading]       = useState(true);
  const [filtre, setFiltre]         = useState('TOUS');

  useEffect(() => {
    api.get('/connexions').then(r => {
      setConnexions(r.data);
      setLoading(false);
    });
  }, []);

  const filtrees = connexions.filter(c => {
    if (filtre === 'TOUS') return true;
    return c.statut === filtre;
  });

  const totalSucces = connexions.filter(c => c.statut === 'SUCCÈS').length;
  const totalEchecs = connexions.filter(c => c.statut === 'ÉCHEC').length;

  if (loading) return <div style={S.loading}>Chargement...</div>;

  return (
    <div>
      {/* Header */}
      <div style={S.header}>
        <div>
          <div style={S.headerTitle}>Historique des connexions</div>
          <div style={S.headerSub}>{connexions.length} entrée(s) enregistrée(s)</div>
        </div>
      </div>

      {/* Métriques */}
      <div style={S.metricsRow}>
        <div style={S.mcard}>
          <div style={{...S.mcardBar, background:'#2ed573'}}/>
          <div style={S.mcardLabel}>CONNEXIONS RÉUSSIES</div>
          <div style={S.mcardVal}>{totalSucces}</div>
        </div>
        <div style={S.mcard}>
          <div style={{...S.mcardBar, background:'#ff4757'}}/>
          <div style={S.mcardLabel}>TENTATIVES ÉCHOUÉES</div>
          <div style={S.mcardVal}>{totalEchecs}</div>
        </div>
        <div style={S.mcard}>
          <div style={{...S.mcardBar, background:'#0099ff'}}/>
          <div style={S.mcardLabel}>TOTAL</div>
          <div style={S.mcardVal}>{connexions.length}</div>
        </div>
        <div style={S.mcard}>
          <div style={{...S.mcardBar, background:'#f5a623'}}/>
          <div style={S.mcardLabel}>TAUX D'ÉCHEC</div>
          <div style={S.mcardVal}>
            {connexions.length > 0 ? Math.round((totalEchecs / connexions.length) * 100) : 0}
            <span style={S.mcardUnit}>%</span>
          </div>
        </div>
      </div>

      {/* Filtres */}
      <div style={S.filtres}>
        {['TOUS', 'SUCCÈS', 'ÉCHEC'].map(f => (
          <button
            key={f}
            style={{...S.filtreBtn, ...(filtre===f ? S.filtreBtnActive : {})}}
            onClick={() => setFiltre(f)}
          >
            {f}
          </button>
        ))}
      </div>

      {/* Table */}
      <div style={S.card}>
        {filtrees.length === 0 ? (
          <div style={S.empty}>Aucune connexion trouvée</div>
        ) : (
          <table style={S.tbl}>
            <thead>
              <tr>
                <th style={S.th}>Horodatage</th>
                <th style={S.th}>Email</th>
                <th style={S.th}>IP</th>
                <th style={S.th}>Statut</th>
              </tr>
            </thead>
            <tbody>
              {filtrees.map(c => (
                <tr key={c.id}>
                  <td style={{...S.td, fontFamily:'Segoe UI', fontSize:12, color:'#7a8394'}}>
                    {new Date(c.horodatage).toLocaleString('fr-FR')}
                  </td>
                  <td style={S.td}>{c.email_tente}</td>
                  <td style={{...S.td, fontFamily:'Segoe UI', fontSize:12, color:'#7a8394'}}>
                    {c.ip || '—'}
                  </td>
                  <td style={S.td}>
                    <span style={{
                      ...S.pill,
                      ...(c.statut === 'SUCCÈS' ? S.pillOk : S.pillErr)
                    }}>
                      {c.statut}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

const S = {
  loading:       { color:'#7a8394', textAlign:'center', marginTop:40 },
  header:        { display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:20 },
  headerTitle:   { fontSize:15, fontWeight:600, color:'#e8eaf0' },
  headerSub:     { fontSize:12, color:'#7a8394', marginTop:4 },
  metricsRow:    { display:'grid', gridTemplateColumns:'repeat(4,1fr)', gap:14, marginBottom:20 },
  mcard:         { background:'#161b22', border:'1px solid rgba(255,255,255,0.07)', borderRadius:10, padding:'18px 20px', position:'relative', overflow:'hidden' },
  mcardBar:      { position:'absolute', top:0, left:0, right:0, height:2 },
  mcardLabel:    { fontFamily:'Segoe UI', fontSize:10, color:'#4a5260', letterSpacing:1.5, textTransform:'uppercase', marginBottom:12 },
  mcardVal:      { fontSize:28, fontWeight:600, color:'#e8eaf0', fontFamily:'Segoe UI' },
  mcardUnit:     { fontSize:13, color:'#7a8394', marginLeft:4 },
  filtres:       { display:'flex', gap:8, marginBottom:16 },
  filtreBtn:     { padding:'6px 14px', background:'transparent', border:'1px solid rgba(255,255,255,0.10)', borderRadius:6, color:'#7a8394', fontSize:12, cursor:'pointer', fontFamily:'Segoe UI' },
  filtreBtnActive:{ background:'rgba(0,212,170,0.10)', borderColor:'rgba(0,212,170,0.30)', color:'#00d4aa' },
  card:          { background:'#161b22', border:'1px solid rgba(255,255,255,0.07)', borderRadius:10, padding:'20px 22px' },
  empty:         { color:'#7a8394', textAlign:'center', padding:'40px 0', fontSize:13 },
  tbl:           { width:'100%', borderCollapse:'collapse' },
  th:            { textAlign:'left', fontFamily:'Segoe UI', fontSize:10, color:'#4a5260', letterSpacing:1, textTransform:'uppercase', paddingBottom:12, borderBottom:'1px solid rgba(255,255,255,0.07)' },
  td:            { padding:'11px 0', borderBottom:'1px solid rgba(255,255,255,0.05)', color:'#e8eaf0', fontSize:13 },
  pill:          { display:'inline-flex', fontFamily:'Segoe UI', fontSize:10, padding:'3px 8px', borderRadius:4 },
  pillOk:        { background:'rgba(46,213,115,0.15)',  color:'#2ed573' },
  pillErr:       { background:'rgba(255,71,87,0.15)',   color:'#ff4757' },
};
